// 이 셋은 그대로 두세요
async function loadCourses(url) {
  const res = await fetch(url);
  if (!res.ok) {
    throw new Error('불러오지 못했습니다 (' + res.status + ')');
  }
  return res.json();
}

function line(className, text) {
  const p = document.createElement('p');
  p.className = className;
  p.textContent = text;
  return p;
}

function draw(nodes) {
  panel.innerHTML = '';
  for (const node of nodes) {
    panel.appendChild(node);
  }
}

const panel = document.querySelector('#panel');

async function show(url) {
  draw([line('state', '불러오는 중…')]);

  try {
    const list = await loadCourses(url);

    if (list.length === 0) {
      draw([line('state', '등록된 코스가 없습니다'), line('hint', '새 코스를 추가해 보세요')]);
      return;
    }

    draw([
      line('state', '코스 ' + list.length + '개'),
      ...list.map((c) => line('course', c.name)),
    ]);
  } catch (e) {
    console.log('개발자용:', e.message);
    draw([line('state', '불러오지 못했습니다'), line('hint', '잠시 뒤 다시 시도해 주세요')]);
  }
}

